import{_ as r,c as e,a5 as p,o as t}from"./chunks/framework.DoP1wijR.js";const o="/pub-blog/assets/image-20250722072751352.Cw9xGbE1.png",i="/pub-blog/assets/image-20250722074951115.B8VYZSzh.png",l="/pub-blog/assets/image-20250722080239722.DTJQaMxq.png",s="/pub-blog/assets/abc.BAPGjQq6.png",n="/pub-blog/assets/image-20250722102348731.Zw31kQ2s.png",h="/pub-blog/assets/image-20250622200325374.BLr7GNE1.png",g="/pub-blog/assets/image-20250722100717843.21U64oy7.png",P=JSON.parse('{"title":"2025 鸿蒙创新赛又来了，万少教你如何强势切入","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/2025 鸿蒙创新赛又来了，万少教你如何强势切入/2025 鸿蒙创新赛又来了，万少教你如何强势切入.md","filePath":"鸿蒙开发技巧/2025 鸿蒙创新赛又来了，万少教你如何强势切入/2025 鸿蒙创新赛又来了，万少教你如何强势切入.md","lastUpdated":1756109794000}'),c={name:"鸿蒙开发技巧/2025 鸿蒙创新赛又来了，万少教你如何强势切入/2025 鸿蒙创新赛又来了，万少教你如何强势切入.md"};function m(d,a,_,b,u,q){return t(),e("div",null,a[0]||(a[0]=[p('<h1 id="_2025-鸿蒙创新赛又来了-万少教你如何强势切入" tabindex="-1">2025 鸿蒙创新赛又来了，万少教你如何强势切入 <a class="header-anchor" href="#_2025-鸿蒙创新赛又来了-万少教你如何强势切入" aria-label="Permalink to &quot;2025 鸿蒙创新赛又来了，万少教你如何强势切入&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>​ 2025 华为<a href="https://developer.huawei.com/consumer/cn/activity/digixActivity/digixcmsdetail/101750143863263087?ha_source=51CTOpo&amp;ha_sourceId=89000408" target="_blank" rel="noreferrer">HarmonyOS 创新赛</a>又来了，创新赛是鸿蒙生态最大规模开发者官方赛事，最高获百万激励。</p><p><img src="'+o+'" alt="一图胜千言"></p><h2 id="参赛资格" tabindex="-1">参赛资格 <a class="header-anchor" href="#参赛资格" aria-label="Permalink to &quot;参赛资格&quot;">​</a></h2><ol><li>面向所有开发者开放</li><li>以队伍的形式来参加，可以一个人报名一个队伍，也可以多个人在一个队伍。</li></ol><h2 id="我也可以吗" tabindex="-1">我也可以吗 <a class="header-anchor" href="#我也可以吗" aria-label="Permalink to &quot;我也可以吗&quot;">​</a></h2><p>参赛的队伍性质，大概可以分为两类</p><ol><li>企业</li><li>个人</li></ol><h3 id="企业" tabindex="-1">企业 <a class="header-anchor" href="#企业" aria-label="Permalink to &quot;企业&quot;">​</a></h3><p>​ 企业的性质一般是站在<strong>公司产品</strong>、战略角度所开发的APP，这一类项目由企业做为绝对的主导，一般的开发者负责参与其中即可，这种情况需要企业负责人多想想如何开发出一款优秀的应用，这就需要结合实际的情况、公司的投入等等来考量了，但是不可否认的是有想要开发鸿蒙产品的公司，确实需要利用好这一个赛事来提速自己的产品，毕竟给的奖励还是不少的。</p><h3 id="个人" tabindex="-1">个人 <a class="header-anchor" href="#个人" aria-label="Permalink to &quot;个人&quot;">​</a></h3><p>​ <strong>这个是这一个文章的重点</strong>，因为大多或多的程序员朋友都还有一个做产品的梦想，但是受限制于各种条件：时间、创意、技术、坚持等等导致自己的项目<strong>流产</strong>了。那么，程序员朋友想要开发一个鸿蒙应用的作品具体该怎么进行呢，这里我们先分享一下开发鸿蒙APP的流程。</p><h2 id="鸿蒙app-和-鸿蒙元服务-的备案、软著解读" tabindex="-1">鸿蒙APP 和 鸿蒙元服务 的备案、软著解读 <a class="header-anchor" href="#鸿蒙app-和-鸿蒙元服务-的备案、软著解读" aria-label="Permalink to &quot;鸿蒙APP 和 鸿蒙元服务 的备案、软著解读&quot;">​</a></h2><p><img src="'+i+'" alt="image-20250722074951115"></p><p>参考以上流程，我们不难得出以下总结</p><ol><li><strong>开发单机的元服务和开发单机的APP</strong>：流程是最简单的，不需要备案、也不需要软著。比如我开发一个单机的图片压缩工具，它使用内置的鸿蒙API便可以完成全部功能，不需要登录、不需要联网。</li><li><strong>开发联网的元服务</strong>：联网的元服务，就需要对元服务进行备案了，备案需要有服务器、域名，这个过程需要经过工信部审核的，流程2-5天左右，你可以选择腾讯云、阿里云、华为云等这些云资源。备案是必须的！。</li><li><strong>开发联网的APP</strong>：如果是开发APP，那么除了备案你的APP之外，还需要进行软著的申请，软著有免费流程也有收费流程，慢的话就一个月，快的话一或两个星期内完成。</li></ol><h2 id="一款产品需要的配套技术" tabindex="-1">一款产品需要的配套技术 <a class="header-anchor" href="#一款产品需要的配套技术" aria-label="Permalink to &quot;一款产品需要的配套技术&quot;">​</a></h2><p><img src="'+l+'" alt="image-20250722080239722"></p><p>如上图，根据开发的作品的选型不同，所涉及到的配套技术也不一样</p><ol><li><strong>开发一款微信：</strong> 由于微信是一个必须要联网，而且业务复杂度巨大的产品，那么只能选择<strong>传统后端</strong>的配套环境，自己买服务器、数据库、云存储等资源，由专门的后端来开发响应的接口，提供服务。</li><li><strong>开发一款读书APP</strong>：读书APP的核心功能相对来说业务复杂度降低了很多，只需要提供基本的书籍类的资讯数据即可，加不加用户账户功能都可以考量取舍的，这类的业务可以使用<strong>端云一体</strong>的技术，降低了服务器运维等相关繁琐的工作，<strong>这一类app是偏向查询类的业务，新增、修改、删除功能几乎 没有</strong>。</li><li><strong>开发一款天气应用</strong>：天气应用可以不接入登录，就只对接第三方天气接口，等于是只有查询功能，没有新增、修改、删除功能。</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>​ 可以看到，如果想要开发一个质量还不错的应用，对于一般的 开发者，尤其是前端开发者来讲，难度还是巨大的！所以，针对这个情况，这一类开发者只有一个解决方案，那么就是抱大腿！抱大腿！抱大腿！抱大腿！抱大腿！抱大腿！抱大腿！</p><p><img src="'+s+'" alt="img"></p><p>​ 找到合适的队伍或者组织或者大佬，抱着他大腿，你拥有了大腿，等于就拥有了大腿的人脉、资源圈。</p><p><strong>我的队伍</strong>：</p><p><img src="'+n+'" alt="image-20250722102348731"></p><h2 id="关于我们" tabindex="-1">关于我们 <a class="header-anchor" href="#关于我们" aria-label="Permalink to &quot;关于我们&quot;">​</a></h2><h3 id="组织信息" tabindex="-1">组织信息 <a class="header-anchor" href="#组织信息" aria-label="Permalink to &quot;组织信息&quot;">​</a></h3><p><a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F" target="_blank" rel="noreferrer">关于青蓝逐码组织</a></p><p>如果你兴趣想要了解更多的鸿<strong>蒙应用开发细节和最新资讯</strong>，<strong>甚至你想要做出一款属于自己的应用</strong>！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。</p><p><img src="'+h+'" alt="image-20250622200325374"></p><hr><h3 id="上架作品" tabindex="-1">上架作品 <a class="header-anchor" href="#上架作品" aria-label="Permalink to &quot;上架作品&quot;">​</a></h3><p><img src="'+g+'" alt="image-20250722100717843"></p><hr><h3 id="过往文章" tabindex="-1">过往文章 <a class="header-anchor" href="#过往文章" aria-label="Permalink to &quot;过往文章&quot;">​</a></h3><ul><li><a href="https://mp.weixin.qq.com/s/l-p25xQxHjdjhhmKkziaTQ" target="_blank" rel="noreferrer">第五款 HarmonyOS 上架作品 奇趣故事匣 来了</a></li><li><a href="https://mp.weixin.qq.com/s/_fjKN9_Qje2fsFEfNlRw7A" target="_blank" rel="noreferrer">我们又来啦 又又上架了一个鸿蒙项目-萤火故事屋</a></li><li><a href="https://mp.weixin.qq.com/s/zALYRljZC0d3vzfzTW9sGg" target="_blank" rel="noreferrer">我们又上架了一个鸿蒙项目-止欲</a></li><li><a href="https://mp.weixin.qq.com/s/DTL5M8yYwK5ajeVhqsOyMA" target="_blank" rel="noreferrer">孵化两个上线项目-谈一谈最近的近况</a></li></ul><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><h3 id="评审规则" tabindex="-1">评审规则 <a class="header-anchor" href="#评审规则" aria-label="Permalink to &quot;评审规则&quot;">​</a></h3><p>比赛的评选机制包含一般奖项和专项奖评审标准。</p><p>1.一般奖项（特等奖、一等奖、二等奖、三等奖）：总分100分=创新性（50分）+完备度（30分）+价值性（20）</p><p>（1)创新性（50分）：在HarmonyOS相关技术的基础上，有技术、设计等方面创新点，满足行业的发展趋势，解决现有痛点问题，富有突破性、具有产业标杆效应。项目所涉及的创新特性应为本次大赛过程中产出。</p><p>（2）完备度（30分）：具备作品所涉及的所有核心功能，在功能、稳定性、用户体验和提交材料等方面完备，复杂功能可只完成可行性验证。</p><p>（3）价值性（20）：</p><p>①商业价值（10）：有明确的市场定位和目标用户，有可行性的商业计划，有清晰的可持续的盈利模式。</p><p>②社会价值（10）：创造积极的社会影响，推动行业进步，包括但不限于医疗健康、教育科普、经济发展、环境保护、公益援助、提升社会资源效率，或有助于解决广泛性社会问题。</p><p>2、专项奖：</p><p>（1）AI智能创新奖：</p><p>基于小艺智能体开放平台，运用大模型、工作流、插件、知识库、记忆等能力，开发具有创新、易用和好用的智能体，必须上架。</p><p>评分标准：创新性（40）+用户体验（30）+功能完备度（30分）</p><p>最佳创新奖（专项奖）：3个</p><p>最具人气奖（专项奖）：3个</p><p>越用越智能奖（专项奖）：4个</p><p>（2）游戏创新奖：</p><p>游戏创新奖：鼓励广大游戏开发者基于HarmonyOS系统的一多适配、碰一碰等创新特性进行游戏开发，为玩家提供玩法更新颖、体验更沉浸的游戏作品。（不强制要求作品在参赛期间上架）</p><p>评分标准：创新玩法（40分）+技术深度（40分）+美术表现（20分）。在满足至少调用3个创新Kit的基础上，其中每接入一个游戏相关的创新Kit加5分，最多加20分。</p><p>最佳跨端游戏奖：2个</p><p>创意玩法突破奖：2个</p><p>最佳视觉艺术奖：2个</p><p>潜力新星游戏奖：2个</p><p>优秀叙事表达奖：2个</p><p>（3）最具社会价值奖：</p><p>在解决社会广泛关注的问题价值突出的优秀作品（社会价值分）；范围：所有参赛作品。</p><p>评分标准：社会问题解决价值（60分）+用户体验与影响力（20分）+作品实现度（20分）</p><p>最具社会价值奖：10个</p><p>（4）场景创新奖：</p><p>作品创意主题不限，可涵盖但不限于智能化、多设备协同、空间化、潮流玩法、社交创新、折叠屏适配、移动轻办公、无障碍等领域，参赛者可自由命题。</p><p>鼓励参赛者结合超级终端、原生智能等HarmonyOS系统特性，以及基于折叠屏、穿戴设备等新设备形态进行创新创意命题。</p><p>要求提交实际应用演示Demo、创意描述、设计稿和介绍文档。</p><p>作品评分标准：创新性（50分）+完备度（20分）+前景评估（20分）+文档质量（10分）</p><p>场景创新奖：10个</p><p>（5）元服务创新奖</p><p>参赛者需调用元服务有价值的开放能力和工具。</p><p>①开放能力五个：服务通知、服务动态、支付服务、地图、扫码；工具：ASCF；</p><p>②要求元服务真实可用，需完成上架；</p><p>评分标准：创新性（40分）+技术深度（40分）+用户体验与设计（20分）</p><p>元服务创新奖：20个</p><p>（6）校园星火奖</p><p>校园开发者个人/团队参与开发的优秀应用；申请该奖项的需在大赛页面补充需提交学生身份证明。</p><p>鼓励学生快速了解鸿蒙生态并开发鸿蒙应用，突出创新潜力，降低门槛，无需上架应用。</p><p>评审标准：创新性（50分）+鸿蒙技术性（30分）+作品完成度（20分）</p><p>校园星火奖：30个</p><p>（7）桃李领航奖：</p><p>协调高校资源，指导团队制定开发计划，帮助团队顺利完成优秀应用；申请该奖项的需在大赛页面补充需提交教师身份证明。</p><p>激励教师组织学生参与，扩大赛事覆盖面。</p><p>评审标准：招募学生/团队规模（50分）+组织成效（30分）+资源整合（20分）。</p><p>桃李领航奖：30个</p>',88)]))}const x=r(c,[["render",m]]);export{P as __pageData,x as default};
